// Hand-authored shared helpers for the scientific-consensus engines. Not
// generated; safe across regeneration (no "Generated by" header).
package cli

import (
	"context"
	"encoding/json"
	"fmt"
	"sort"
	"strconv"
	"strings"

	"github.com/mvanhorn/printing-press-library/library/other/scientific-consensus/internal/scengine"
	"github.com/mvanhorn/printing-press-library/library/other/scientific-consensus/internal/source"
)

// scWork is the normalized work record the engines operate on. It is populated
// primarily from OpenAlex and optionally enriched from secondary sources.
type scWork struct {
	ID          string   `json:"id"`
	DOI         string   `json:"doi,omitempty"`
	PMID        string   `json:"pmid,omitempty"`
	Title       string   `json:"title"`
	Abstract    string   `json:"-"`
	Year        int      `json:"year,omitempty"`
	Type        string   `json:"type,omitempty"`
	CitedBy     int      `json:"cited_by_count"`
	Venue       string   `json:"venue,omitempty"`
	Topic       string   `json:"topic,omitempty"`
	IsOA        bool     `json:"is_oa,omitempty"`
	PubTypes    []string `json:"-"`
	FirstAuthor string   `json:"first_author,omitempty"`
	Country     string   `json:"-"`
	// Retraction carries the work's retraction status, derived once here from
	// the title and OpenAlex's is_retracted flag so every consumer sees the
	// same answer. The zero value is scengine.NotRetracted, so callers that
	// never look at it behave exactly as before.
	Retraction scengine.Retraction `json:"retraction,omitempty"`
}

// openAlexWorksResponse mirrors the slice of the OpenAlex /works payload the
// engines need.
type openAlexWorksResponse struct {
	Meta struct {
		Count int `json:"count"`
	} `json:"meta"`
	Results []openAlexWork `json:"results"`
	GroupBy []struct {
		Key            string `json:"key"`
		KeyDisplayName string `json:"key_display_name"`
		Count          int    `json:"count"`
	} `json:"group_by"`
}

type openAlexWork struct {
	ID              string `json:"id"`
	DOI             string `json:"doi"`
	Title           string `json:"title"`
	DisplayName     string `json:"display_name"`
	PublicationYear int    `json:"publication_year"`
	CitedByCount    int    `json:"cited_by_count"`
	Type            string `json:"type"`
	OpenAccess      struct {
		IsOA bool `json:"is_oa"`
	} `json:"open_access"`
	// IsRetracted is OpenAlex's retraction flag. Measured to over-mark (a
	// correction on the 2020 Lancet dementia Commission reads as retracted),
	// which is why DetectRetraction keeps it in a softer tier than a title
	// marker rather than treating it as ground truth.
	IsRetracted           bool             `json:"is_retracted"`
	AbstractInvertedIndex map[string][]int `json:"abstract_inverted_index"`
	IDs                   struct {
		Pmid string `json:"pmid"`
	} `json:"ids"`
	PrimaryTopic struct {
		DisplayName string `json:"display_name"`
	} `json:"primary_topic"`
	PrimaryLocation struct {
		Source struct {
			DisplayName string `json:"display_name"`
		} `json:"source"`
	} `json:"primary_location"`
	Authorships []struct {
		Author struct {
			DisplayName string `json:"display_name"`
		} `json:"author"`
		Institutions []struct {
			CountryCode string `json:"country_code"`
		} `json:"institutions"`
	} `json:"authorships"`
}

// defaultMailto is OpenAlex's polite-pool courtesy parameter.
const defaultMailto = "scientific-consensus-pp-cli@users.noreply.github.com"

// fetchWorks queries OpenAlex /works and returns normalized works. search is the
// query; filter is an optional OpenAlex filter expression; perPage caps results
// (<=200). Abstracts are reconstructed from the inverted index.
func fetchWorks(ctx context.Context, c apiGetter, search, filter, sortBy string, perPage int) ([]scWork, int, error) {
	if perPage <= 0 {
		perPage = 50
	}
	if perPage > 200 {
		perPage = 200
	}
	params := map[string]string{
		"per-page": strconv.Itoa(perPage),
		"mailto":   defaultMailto,
		"select":   "id,doi,title,display_name,publication_year,cited_by_count,type,open_access,abstract_inverted_index,ids,primary_topic,primary_location,authorships,is_retracted",
	}
	if search != "" {
		params["search"] = search
	}
	if filter != "" {
		params["filter"] = filter
	}
	if sortBy != "" {
		params["sort"] = sortBy
	}
	raw, err := c.Get(ctx, "/works", params)
	if err != nil {
		return nil, 0, err
	}
	var resp openAlexWorksResponse
	if err := json.Unmarshal(raw, &resp); err != nil {
		return nil, 0, fmt.Errorf("parsing OpenAlex works: %w", err)
	}
	out := make([]scWork, 0, len(resp.Results))
	for _, w := range resp.Results {
		title := w.Title
		if title == "" {
			title = w.DisplayName
		}
		sw := scWork{
			ID:       w.ID,
			DOI:      strings.TrimPrefix(w.DOI, "https://doi.org/"),
			PMID:     extractPMID(w.IDs.Pmid),
			Title:    title,
			Abstract: scengine.ReconstructAbstract(w.AbstractInvertedIndex),
			Year:     w.PublicationYear,
			Type:     w.Type,
			CitedBy:  w.CitedByCount,
			Venue:    w.PrimaryLocation.Source.DisplayName,
			Topic:    w.PrimaryTopic.DisplayName,
			IsOA:     w.OpenAccess.IsOA,
			// title, not title+abstract: DetectRetraction is start-anchored,
			// and joining would leave the abstract silently unguarded.
			Retraction: scengine.DetectRetraction(title, w.IsRetracted),
		}
		if len(w.Authorships) > 0 {
			sw.FirstAuthor = w.Authorships[0].Author.DisplayName
			for _, inst := range w.Authorships[0].Institutions {
				if inst.CountryCode != "" {
					sw.Country = inst.CountryCode
					break
				}
			}
		}
		out = append(out, sw)
	}
	return out, resp.Meta.Count, nil
}

// fetchGroupBy runs an OpenAlex group_by facet query against the given entity
// path (e.g. "/works", "/authors") and returns the facet rows.
func fetchGroupBy(ctx context.Context, c apiGetter, path, search, filter, groupBy string) ([]groupRow, error) {
	params := map[string]string{
		"group_by": groupBy,
		"mailto":   defaultMailto,
		"per-page": "200",
	}
	if search != "" {
		params["search"] = search
	}
	if filter != "" {
		params["filter"] = filter
	}
	raw, err := c.Get(ctx, path, params)
	if err != nil {
		return nil, err
	}
	var resp openAlexWorksResponse
	if err := json.Unmarshal(raw, &resp); err != nil {
		return nil, fmt.Errorf("parsing group_by: %w", err)
	}
	out := make([]groupRow, 0, len(resp.GroupBy))
	for _, g := range resp.GroupBy {
		name := g.KeyDisplayName
		if name == "" {
			name = g.Key
		}
		out = append(out, groupRow{Key: g.Key, Name: name, Count: g.Count})
	}
	return out, nil
}

type groupRow struct {
	Key   string `json:"key"`
	Name  string `json:"name"`
	Count int    `json:"count"`
}

// classifyWorks runs the evidence classifier over a slice of works, using any
// PubTypes already attached.
func classifyWorks(works []scWork) []scengine.Classification {
	cs := make([]scengine.Classification, len(works))
	for i, w := range works {
		cs[i] = scengine.ClassifyDesign(w.Title, w.Abstract, w.Type, w.PubTypes)
	}
	return cs
}

// scoreWorks builds the consensus engine input from works + per-work stance.
// ctx bounds the optional per-work LLM stance calls so --timeout and Ctrl+C
// propagate; the heuristic path never blocks on it.
func scoreWorks(ctx context.Context, works []scWork, claim string) ([]scengine.ScoredWork, []workStance) {
	scored := make([]scengine.ScoredWork, len(works))
	stances := make([]workStance, len(works))
	for i, w := range works {
		cls := scengine.ClassifyDesign(w.Title, w.Abstract, w.Type, w.PubTypes)
		st, conf, stMethod := scengine.ClassifyStanceAuto(ctx, w.Title, w.Abstract, claim)
		scored[i] = scengine.ScoredWork{Stance: st, StanceConf: conf, Design: cls.Design, CitedBy: w.CitedBy}
		stances[i] = workStance{Work: w, Stance: st, Confidence: conf, Design: cls.Design, Method: cls.Method, StanceMethod: stMethod}
	}
	return scored, stances
}

// scorableWorks splits the output of scoreWorks into the works that may enter
// the consensus score and a count of those withheld because they are retracted.
//
// Shared rather than inlined at each call site because consensus, compare and
// batch must measure the SAME subset — the existing comment in computeConsensus
// says so about the relevance gates, and a retraction gate that drifted between
// the two commands would produce two different scores for one claim, which is
// worse than having no gate at all.
//
// scored and stances are index-aligned by construction (scoreWorks fills both
// in a single loop), so filtering by index preserves each work's own values.
// The input slices are not mutated.
func scorableWorks(scored []scengine.ScoredWork, stances []workStance) ([]scengine.ScoredWork, int) {
	out := make([]scengine.ScoredWork, 0, len(scored))
	excluded := 0
	for i := range stances {
		if i >= len(scored) {
			break
		}
		if stances[i].Work.Retraction.ExcludeFromScore() {
			excluded++
			continue
		}
		out = append(out, scored[i])
	}
	return out, excluded
}

type workStance struct {
	Work       scWork          `json:"work"`
	Stance     scengine.Stance `json:"stance"`
	Confidence float64         `json:"stance_confidence"`
	Design     scengine.Design `json:"design"`
	Method     scengine.Method `json:"classification_method"`
	// StanceMethod records how stance was derived: "heuristic" or
	// "llm:<provider>". Empty for callers that don't run the dispatcher.
	StanceMethod string `json:"stance_method,omitempty"`
}

// How many DISTINCT claim stems a work must share with the claim to survive the
// relevance gate.
//
// Two, not one. A single shared stem is satisfied by any paper that mentions
// one half of the claim, which is how a vitamin K ferroptosis study and a paper
// on cold-dependent anthocyanin accumulation in blood oranges both reached the
// score for "vitamin C prevents the common cold" — the first on `vitam`, the
// second on `cold` — and were then classified with 0.90 stance confidence.
//
// One, when the work carries no abstract. The second stem would have to come
// from text the record does not have, so demanding it would exclude works for a
// property of OpenAlex's coverage rather than of their content. That is not
// hypothetical: 52 of the 295 archived studies (17.6%) have no abstract. The
// guard restores exactly the pre-V6 rule for those works, which is why widening
// the haystack could not move the calibrated harm corpora.
//
// Both thresholds count DISTINCT stems: one stem found twice is one match.
const (
	relevanceMinTokens           = 2
	relevanceMinTokensNoAbstract = 1
)

// claimRelevanceStems returns the claim's content tokens, truncated so inflected
// forms still match, de-duplicated, and in claim order.
//
// THE 5 BELOW IS AN INLINE LITERAL ON PURPOSE. It is deliberately NOT
// scengine.claimStemLen, which happens to hold the same value but drives the
// stance harm path (classifyAgainstHarmClaim) and the PICO gate (pico.go).
// Those are calibrated against the harm corpora; merging the two would mean a
// future adjustment to either one silently re-tunes the other. Raising this
// specific truncation to 7 was measured and is inert — at seven characters
// `vitamin` is still `vitamin`, so it still matches "vitamin K" — so there is no
// reason to touch it and every reason not to couple it.
func claimRelevanceStems(claim string) []string {
	tokens := scengine.ClaimContentTokens(claim)
	stems := make([]string, 0, len(tokens))
	seen := make(map[string]bool, len(tokens))
	for _, tok := range tokens {
		stem := tok
		if len(stem) > 5 {
			stem = stem[:5]
		}
		if seen[stem] {
			continue
		}
		seen[stem] = true
		stems = append(stems, stem)
	}
	return stems
}

// relevantToClaim reports whether a work shares enough content with the claim to
// be worth classifying. The haystack is Abstract + Title + Topic; the bar is
// relevanceMinTokens distinct claim stems, or relevanceMinTokensNoAbstract when
// the work has no abstract.
//
// Still conservative by design: a claim that yields no content tokens disables
// the gate entirely (keep everything), because a gate that cannot name what it
// is filtering for must not filter.
//
// Known limit, not a defect: this is lexical, so it does not know that `omega-3`
// is `n-3` is `EPA` is `DHA`, or that "cardiovascular health" is what an
// endothelial-function paper measures. V6 does not make that worse than the
// single-token rule did; it just does not fix it.
func relevantToClaim(claim string, w scWork) bool {
	keep, _ := relevanceVerdict(claim, w)
	return keep
}

// relevanceVerdict is relevantToClaim plus the threshold that decided it, so a
// caller can report WHY a work was excluded instead of only how many were. A
// silent gate is the failure mode this whole change exists to repair: on the
// vitamin C corpus the exclusion count goes from 1 work to 17.
//
// required is 0 when the gate is disabled (the claim has no content tokens).
func relevanceVerdict(claim string, w scWork) (keep bool, required int) {
	stems := claimRelevanceStems(claim)
	if len(stems) == 0 {
		return true, 0
	}
	required = relevanceMinTokens
	if strings.TrimSpace(w.Abstract) == "" {
		required = relevanceMinTokensNoAbstract
	}
	// Abstract first, then Title, then Topic. The order cannot change a result —
	// a stem never contains a space, so none can straddle a join — but it is the
	// order the regression harness reproduces.
	hay := strings.ToLower(w.Abstract + " " + w.Title + " " + w.Topic)
	hits := 0
	for _, stem := range stems {
		if !strings.Contains(hay, stem) {
			continue
		}
		hits++
		if hits >= required {
			return true, required
		}
	}
	return false, required
}

// relevanceReport is the relevance gate's contribution to the PRISMA ledger:
// what it was given, what it kept, and the rule it applied. Carrying the stems
// and the thresholds rather than a rendered sentence keeps the accounting
// checkable and lets the caller decide how to phrase it.
type relevanceReport struct {
	Fetched  int
	Kept     int
	Excluded int
	// Stems is what the gate searched for. Empty means the claim yielded no
	// content tokens and the gate was therefore disabled, which is a different
	// statement from "nothing was excluded".
	Stems               []string
	MinTokens           int
	MinTokensNoAbstract int
}

// filterRelevant drops works that fail the relevance gate so they never reach
// classification or scoring. Returns a new slice; the input is not mutated.
func filterRelevant(claim string, works []scWork) []scWork {
	kept, _ := filterRelevantReport(claim, works)
	return kept
}

// filterRelevantReport is filterRelevant with the ledger attached, for callers
// that must be able to say how many works the gate removed and under what rule.
func filterRelevantReport(claim string, works []scWork) ([]scWork, relevanceReport) {
	rep := relevanceReport{
		Fetched:             len(works),
		Stems:               claimRelevanceStems(claim),
		MinTokens:           relevanceMinTokens,
		MinTokensNoAbstract: relevanceMinTokensNoAbstract,
	}
	kept := make([]scWork, 0, len(works))
	for _, w := range works {
		if relevantToClaim(claim, w) {
			kept = append(kept, w)
		}
	}
	rep.Kept = len(kept)
	rep.Excluded = rep.Fetched - rep.Kept
	return kept, rep
}

// extractPMID pulls the numeric PMID out of an OpenAlex pmid URL.
func extractPMID(u string) string {
	if u == "" {
		return ""
	}
	i := strings.LastIndex(u, "/")
	if i >= 0 && i < len(u)-1 {
		return u[i+1:]
	}
	return u
}

// sortWorksByCitations sorts descending by citation count (stable).
func sortWorksByCitations(works []scWork) {
	sort.SliceStable(works, func(i, j int) bool { return works[i].CitedBy > works[j].CitedBy })
}

// apiGetter is the subset of *client.Client the engines need. Declared as an
// interface so engine helpers can be unit-tested with a stub.
type apiGetter interface {
	Get(ctx context.Context, path string, params map[string]string) (json.RawMessage, error)
}

// enrichPubTypes best-effort augments works that have a PMID with authoritative
// PubMed publication types. Errors are swallowed (enrichment is optional). cap
// bounds how many PMIDs are looked up to keep latency bounded.
func enrichPubTypes(ctx context.Context, works []scWork, capN int) {
	pmids := make([]string, 0, len(works))
	idx := map[string]int{}
	for i := range works {
		if works[i].PMID != "" && len(pmids) < capN {
			pmids = append(pmids, works[i].PMID)
			idx[works[i].PMID] = i
		}
	}
	if len(pmids) == 0 {
		return
	}
	types, err := source.PubMedPubTypes(ctx, pmids)
	if err != nil {
		return
	}
	for pmid, pts := range types {
		if i, ok := idx[pmid]; ok {
			works[i].PubTypes = pts
		}
	}
}
